from dataclasses import dataclass

@dataclass(frozen=True)
class InterviewPrompt:
    category: str
    role: str
    seniority: str
    question: str
    signals: tuple[str, ...]
    follow_ups: tuple[str, ...]
    def search_text(self) -> str:
        return ' '.join((self.category,self.role,self.seniority,self.question,*self.signals)).lower()

INTERVIEW_PROMPTS: list[InterviewPrompt] = []

