def find_interview_prompts(query: str, limit: int = 25) -> list[InterviewPrompt]:
    tokens = {token for token in query.lower().split() if token}
    scored = []
    for prompt in INTERVIEW_PROMPTS:
        haystack = prompt.search_text()
        score = sum(token in haystack for token in tokens)
        if score:
            scored.append((score, prompt))
    scored.sort(key=lambda item: (-item[0], item[1].category, item[1].role))
    return [prompt for _, prompt in scored[:limit]]


def prompts_for_role(role: str, seniority: str = "", limit: int = 25) -> list[InterviewPrompt]:
    matches=[
        prompt for prompt in INTERVIEW_PROMPTS
        if role.lower() in prompt.role.lower()
        and (not seniority or seniority.lower() == prompt.seniority)
    ]
    return matches[:limit]
